<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Kanban Board</title>
<style>
    :root {
        --bg-body: #f4f5f7;
        --col-bg: #ffffff;
        --card-bg: #fff;
        --text-main: #1e2328;
        --text-muted: #6a737d;
        --border-color: #d0d7de;
        --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.12);
        --primary-btn-bg: #0969da;
        --primary-btn-hover: #085ba4;
    }

    body {
        margin: 0;
        padding: 20px;
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
        background-color: var(--bg-body);
        color: var(--text-main);
        display: flex;
        flex-direction: column;
    }

    /* Input Area */
    .input-area {
        margin-bottom: 20px;
        max-width: 600px;
        width: 100%;
    }

    #new-card {
        padding: 8px 12px;
        border-radius: 4px;
        border: 1px solid var(--border-color);
        font-size: 14px;
        outline: none;
    }

    #add-card {
        margin-left: 8px;
        padding: 8px 12px;
        background-color: var(--primary-btn-bg);
        color: white;
        border: none;
        border-radius: 4px;
        font-size: 14px;
        cursor: pointer;
    }

    #add-card:hover {
        background-color: var(--primary-btn-hover);
    }

    /* Board Layout */
    .board {
        display: flex;
        gap: 20px;
        overflow-x: auto;
        padding-bottom: 10px;
    }

    /* Columns */
    .column {
        background-color: var(--col-bg);
        border-radius: 8px;
        width: 300px;
        min-width: 260px;
        display: flex;
        flex-direction: column;
        box-shadow: var(--shadow-sm);
        padding: 10px;
    }

    .column h3 {
        margin: 0 0 15px 0;
        font-size: 14px;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.5px;
        display: flex;
        justify-content: space-between;
        align-items: center;
    }

    .count {
        background-color: var(--bg-body);
        color: var(--text-muted);
        font-size: 12px;
        padding: 2px 8px;
        border-radius: 10px;
        min-width: 24px;
        text-align: center;
    }

    /* Card Container */
    .card-container {
        flex-grow: 1;
        background-color: #fff;
        overflow-y: auto;
        padding-right: 5px;
    }

    /* Cards */
    .card {
        background-color: var(--card-bg);
        border: 1px solid var(--border-color);
        box-shadow: var(--shadow-sm);
        margin-bottom: 8px;
        padding: 10px;
        border-radius: 4px;
        position: relative;
    }

    .card:hover {
        background-color: #f6f8fa;
    }

    .card-title {
        font-size: 14px;
        word-break: break-word;
        margin-right: 30px; /* Space for delete */
    }

    .card-del {
        position: absolute;
        top: 8px;
        right: 6px;
        background: none;
        border: none;
        color: var(--text-muted);
        font-size: 12px;
        cursor: pointer;
        opacity: 0.7;
    }

    .card-del:hover {
        opacity: 1;
        color: #cf3a2e; /* Red on hover */
    }

    /* Dragging Visuals */
    body.dragging-over-column .column, 
    .drag-target-active .column {
        background-color: #f0f4ff;
        border: 1px dashed var(--primary-btn-bg);
        padding: 8px; /* Adjust to match visual shift if needed */
    }

</style>
</head>
<body>

<div class="input-area">
    <input type="text" id="new-card" placeholder="Add a new card...">
    <button id="add-card">Add Card</button>
</div>

<div class="board">
    <!-- Column 1: To Do -->
    <div id="col-todo" class="column">
        <h3>To Do <span class="count"></span></h3>
        <div class="card-container" id="cont-todo"></div>
    </div>

    <!-- Column 2: Doing -->
    <div id="col-doing" class="column">
        <h3>Doing <span class="count"></span></h3>
        <div class="card-container" id="cont-doing"></div>
    </div>

    <!-- Column 3: Done -->
    <div id="col-done" class="column">
        <h3>Done <span class="count"></span></h3>
        <div class="card-container" id="cont-done"></div>
    </div>
</div>

<script>
(function() {
    // Configuration & State
    const STORAGE_KEY = 'kanban_state';

    let state = {
        'col-todo': [],
        'col-doing': [],
        'col-done': []
    };

    // DOM Elements
    const inputEl = document.getElementById('new-card');
    const addBtn = document.getElementById('add-card');
    const containers = {
        'todo': document.getElementById('cont-todo'),
        'doing': document.getElementById('cont-doing'),
        'done': document.getElementById('cont-done')
    };

    // Column IDs map to container keys (assuming id="col-<key>")
    const colIdsMap = {
        'todo': '#col-todo',
        'doing': '#col-doing',
        'done': '#col-done'
    };

    // --- Initialization & Persistence ---

    function loadState() {
        try {
            const raw = localStorage.getItem(STORAGE_KEY);
            if (raw) {
                state = JSON.parse(raw);
                // Ensure structure integrity for keys that might be missing in old storage
                ['col-todo', 'col-doing', 'col-done'].forEach(k => {
                    if (!state[k]) state[k] = [];
                });
            }
        } catch (e) {
            console.error('Failed to load state:', e);
        }
    }

    function saveState() {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    }

    // --- Rendering Logic ---

    function renderBoard() {
        // Clear all containers first (simple approach for consistency)
        Object.values(containers).forEach(c => c.innerHTML = '');

        ['todo', 'doing', 'done'].forEach(key => {
            const colId = `col-${key}`;
            const countEl = document.querySelector(`${colId} .count`);

            // Render Cards for this column
            state[colId].forEach(cardObj => {
                renderCard(cardObj, containers[key]);
            });

            // Update Count (Live count from State)
            if (countEl) {
                countEl.textContent = state[colId].length;
            }
        });
    }

    function renderCard(cardObj, containerEl) {
        const cardDiv = document.createElement('div');
        cardDiv.className = 'card';
        // Unique ID for DOM lookup during Drag and Drop / Delete logic if needed, though we use DataTransfer ID.
        cardDiv.id = `card-${cardObj.id}`;
        cardDiv.draggable = true;

        const titleSpan = document.createElement('span');
        titleSpan.className = 'card-title';
        titleSpan.textContent = cardObj.title;

        const delBtn = document.createElement('button');
        delBtn.className = 'card-del';
        delBtn.innerHTML = '&times;';
        delBtn.ariaLabel = 'Delete card';

        // Delete Event - find this specific DOM element's ID context or rely on global search?
        // Simpler: attach click listener directly to the button and look up state via cardObj.id (if closure captures it) OR event delegation.
        // We'll use delegation for better performance, but here we create elements in a loop so direct binding is fine too.

        delBtn.onclick = function(e) {
            e.stopPropagation(); 
            deleteCard(cardObj.id);
        };

        cardDiv.appendChild(titleSpan);
        cardDiv.appendChild(delBtn);

        // Drag Start Event
        cardDiv.addEventListener('dragstart', function(e) {
            e.dataTransfer.setData('text/plain', String(cardObj.id));
            // Visual feedback: slightly dim or mark dragged element (optional, handled via CSS on body/container usually)
            setTimeout(() => cardDiv.style.opacity = '0.5', 0);
        });

        cardDiv.addEventListener('dragend', function(e) {
            cardDiv.style.opacity = '1';
        });

        containerEl.appendChild(cardDiv);
    }

    // --- Actions: Add, Delete, Move ---

    function addCard(titleText) {
        if (!titleText.trim()) return;

        const newId = Date.now().toString(36) + Math.random().toString(36).substr(2);

        state['col-todo'].push({ id: newId, title: titleText });

        saveState();
        renderBoard(); // Re-render to show card

        inputEl.value = '';
    }

    function deleteCard(cardId) {
        // Find which column this ID belongs to and remove it.
        ['col-todo', 'col-doing', 'col-done'].forEach(col => {
            const index = state[col].findIndex(c => c.id === cardId);
            if (index > -1) {
                state[col].splice(index, 1);
                saveState();
                renderBoard(); // Re-render to remove card and update counts
            }
        });
    }

    function moveCard(cardId, targetColKey) {
        let sourceCol = null;

        // Find current column (source)
        ['col-todo', 'col-doing', 'col-done'].forEach(col => {
            const index = state[col].findIndex(c => c.id === cardId);
            if (index > -1) {
                sourceCol = col;
                return; // found
            }
        });

        if (!sourceCol || sourceCol === targetColKey) return; // Already there or not found

        // Remove from source
        const indexToRemove = state[sourceCol].findIndex(c => c.id === cardId);
        state[sourceCol].splice(indexToRemove, 1);

        // Add to destination (at end for simplicity as per "moves it there")
        state[targetColKey].push(state[sourceCol][indexToRemove] || {id:cardId, title:'(Moved)' }); // Should work from previous line but safe guard

        saveState();
        renderBoard();
    }

    // --- Event Listeners ---

    addBtn.addEventListener('click', () => {
        const txt = inputEl.value;
        if (txt.trim()) addCard(txt);
    });

    inputEl.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') {
            const txt = inputEl.value;
            if (txt.trim()) addCard(txt);
        }
    });

    // Drag and Drop Setup on Containers
    ['todo', 'doing', 'done'].forEach(key => {
        const container = containers[key];

        container.addEventListener('dragover', function(e) {
            e.preventDefault(); // Allow dropping

            // Optional: Visual feedback class (removed later in dropend or similar)
            document.body.classList.add('dragging-over-column');

            // We need to know the target column ID for moveCard. 
            // The container key 'todo' maps to colId '#col-todo'.
        });

        container.addEventListener('dragleave', function() {
             document.body.classList.remove('dragging-over-column');
        });

        container.addEventListener('drop', function(e) {
            e.preventDefault();
            document.body.classList.remove('dragging-over-column');

            const cardId = e.dataTransfer.getData('text/plain');

            if (cardId) {
                // Determine target column ID string from our map (e.g., 'col-todo')
                const colIdKey = `col-${key}`; 
                moveCard(cardId, colIdKey);
            }
        });
    });

    // --- Init ---

    loadState();
    renderBoard();

})();
</script>

</body>
</html>
